import { makeMemberSummary } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function expectRange(fn: () => unknown, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const roles = [' editor ', '', 'Admin', 'editor', '  ', 'admin'];
const member = {
  handle: '  forge  ',
  contact: '  forge@example.test  ',
  note: '  hello  ',
  icon: '  avatar.png  ',
  roles
};
const before = JSON.stringify(member);
const summary = makeMemberSummary(member);
deepEqual(summary, {
  title: 'forge',
  contact: 'forge@example.test',
  note: 'hello',
  icon: 'avatar.png',
  roles: ['Admin', 'admin', 'editor']
}, 'member fields are trimmed and roles are filtered, deduplicated, and code-point sorted');
assert(JSON.stringify(member) === before, 'member and roles are not mutated');
assert(summary.roles !== roles, 'result roles array is newly allocated');

const second = makeMemberSummary(member);
assert(second !== summary, 'result object is new on every call');
assert(second.roles !== summary.roles, 'result roles array is new on every call');
summary.roles.push('external');
deepEqual(second.roles, ['Admin', 'admin', 'editor'], 'result role arrays do not alias each other');

deepEqual(makeMemberSummary({ handle: 'x', contact: 'y', note: ' ', icon: null, roles: [] }), {
  title: 'x', contact: 'y', note: '', icon: 'default-icon', roles: []
}, 'null icon uses default');
deepEqual(makeMemberSummary({ handle: 'x', contact: 'y', note: '', icon: '   ', roles: [] }).icon, 'default-icon', 'blank icon uses default');
expectRange(() => makeMemberSummary({ handle: '  ', contact: 'x', note: '', icon: null, roles: [] }), 'blank handle is rejected');
expectRange(() => makeMemberSummary({ handle: 'x', contact: '\t ', note: '', icon: null, roles: [] }), 'blank contact is rejected');

